begin;
alter table public.schema_versions add column manifest jsonb not null default '{}';
alter table public.xml_validations add column filename text not null default 'documento.xml';
alter table public.xml_validations add column sha256 text check(sha256 ~ '^[a-f0-9]{64}$');
alter table public.xml_validations add column original_path text;
alter table public.xml_validations add column report jsonb not null default '{}';
alter table public.xml_validations drop constraint xml_validations_user_id_document_id_fkey;
alter table public.xml_validations add foreign key(user_id,document_id) references public.fiscal_documents(user_id,id) on delete set null(document_id);

create function public.save_xml_validation(p_id uuid,p_report jsonb,p_path text,p_document_id uuid default null)
returns uuid language plpgsql security invoker set search_path='' as $$
declare owner_id uuid:=(select auth.uid()); selected_schema uuid; issue jsonb;
begin
 if owner_id is null or not public.has_active_session() then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_path is distinct from owner_id::text||'/validations/'||p_id::text||'.xml' then raise exception 'Invalid original path'; end if;
 if octet_length(p_report::text)>1048576 or jsonb_typeof(p_report->'issues') is distinct from 'array' or jsonb_array_length(p_report->'issues')>200 then raise exception 'Invalid report'; end if;
 if p_report->>'structure' not in ('passed','failed','not_verified') or p_report->>'xsd' not in ('passed','failed','not_verified') or p_report->>'rules' not in ('passed','failed','not_verified') then raise exception 'Invalid results'; end if;
 if p_report->'schema'->>'id' is not null then
  select id into selected_schema from public.schema_versions where name=p_report->'schema'->>'id' and sha256=p_report->'schema'->>'bundleHash';
  if selected_schema is null then raise exception 'Schema not installed'; end if;
 end if;
 insert into public.xml_validations(id,user_id,document_id,schema_id,document_type,layout_version,access_key,structural_result,xsd_result,rules_result,error_count,warning_count,checks_run,not_verified,filename,sha256,original_path,report)
 values(p_id,owner_id,p_document_id,selected_schema,p_report->>'documentType',p_report->>'layoutVersion',p_report->>'accessKey',p_report->>'structure',p_report->>'xsd',p_report->>'rules',(p_report->>'errors')::integer,(p_report->>'warnings')::integer,(p_report->>'checksRun')::integer,p_report->'notVerified',left(p_report->>'filename',240),p_report->>'sha256',p_path,p_report);
 for issue in select value from jsonb_array_elements(p_report->'issues') loop
  insert into public.validation_issues(user_id,validation_id,severity,level,rule_id,rejection_code,message,tag,xpath,line,column_number,found_value,expected_value,reason,suggestion,source)
  values(owner_id,p_id,issue->>'severity',issue->>'level',issue->>'ruleId',issue->>'rejectionCode',issue->>'message',issue->>'tag',issue->>'xpath',(issue->>'line')::integer,(issue->>'column')::integer,issue->>'found',issue->>'expected',issue->>'reason',issue->>'suggestion',issue->'source');
 end loop;
 return p_id;
end $$;
revoke all on function public.save_xml_validation(uuid,jsonb,text,uuid) from public,anon;
grant execute on function public.save_xml_validation(uuid,jsonb,text,uuid) to authenticated;
create function private.validation_activity() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if (select auth.uid())=new.user_id then insert into public.activity_events(user_id,action) values(new.user_id,'xml_validated'); end if;
 return new;
end $$;
revoke all on function private.validation_activity() from public,anon,authenticated;
create trigger validation_activity after insert on public.xml_validations for each row execute function private.validation_activity();
